insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4031,38,61,'قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَـٰذَا فَزِدْهُ عَذَابًا ضِعْفًا فِى ٱلنَّارِ','221a4753ab204ec7ed5d70eaecf7fca0778481eb8392b49f644ebbf573bd8d2d',23,456,1);
