insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4051,38,81,'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ','ed860cfd3749d7c7ba6f1cff8c99eb8f4fd2d83cde0bb829de851da2bdc743d9',23,457,1);
