insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4054,38,84,'قَالَ فَٱلْحَقُّ وَٱلْحَقَّ أَقُولُ','40eb9577b8c0f500f9f138282f8de3bd26052d85ec28f3ef9d208cb7648ebe95',23,458,1);
