insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4476,45,3,'إِنَّ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّلْمُؤْمِنِينَ','f7a86d642683e2837b966d18b1d8127b5566f4555853d2ef109683edd805a17e',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4477,45,4,'وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَـٰتٌ لِّقَوْمٍ يُوقِنُونَ','6f3679cca525624036a18cd257d3b34e2e5c8b14367a06d3f77671f2f2b72a42',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4478,45,5,'وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزْقٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ ٱلرِّيَـٰحِ ءَايَـٰتٌ لِّقَوْمٍ يَعْقِلُونَ','462d5b56bd57c2ecd7cca631831423c279c27257dfa8649b8a5d875f6f7844a2',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4479,45,6,'تِلْكَ ءَايَـٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَ ٱللَّهِ وَءَايَـٰتِهِۦ يُؤْمِنُونَ','537b4d1e15ad93c38af10a565952a6f1ca702f5afaa600ed04a6d9e7a6513571',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4480,45,7,'وَيْلٌ لِّكُلِّ أَفَّاكٍ أَثِيمٍ','79da3bc689145187ff901f5611302f6c80306cade2f57d1ad1709a17167c74aa',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4481,45,8,'يَسْمَعُ ءَايَـٰتِ ٱللَّهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ','3421f91e1f422648030b2d7f13ad2f4783e15cfc3493ccfc036f858604534142',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4482,45,9,'وَإِذَا عَلِمَ مِنْ ءَايَـٰتِنَا شَيْـًٔا ٱتَّخَذَهَا هُزُوًا ۚ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ','b5e5a753fcf89837e93bc41177e8bdc82e0edfc5259edcd28f755800c1e94c10',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4483,45,10,'مِّن وَرَآئِهِمْ جَهَنَّمُ ۖ وَلَا يُغْنِى عَنْهُم مَّا كَسَبُوا۟ شَيْـًٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ','db1cb57e5db9fc402e1360311d292f1cc3aeb8b1ea640c83508fe362bf90033d',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4484,45,11,'هَـٰذَا هُدًى ۖ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ','40d7868e62a28a5e475f13bef67aa2303ac3cbf40b59681d97164236cdafc325',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4485,45,12,'ٱللَّهُ ٱلَّذِى سَخَّرَ لَكُمُ ٱلْبَحْرَ لِتَجْرِىَ ٱلْفُلْكُ فِيهِ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ','5addf8fa9cfae52358b283e242581ddda282638b4bbd76dcfd78e6291f45197a',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4486,45,13,'وَسَخَّرَ لَكُم مَّا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ جَمِيعًا مِّنْهُ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ','cf0f58f52a9404d0a4354bc8b3bd8e85fd1a1ce3049da5ba0b2ca5b0acb5bc15',25,499,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4487,45,14,'قُل لِّلَّذِينَ ءَامَنُوا۟ يَغْفِرُوا۟ لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ ٱللَّهِ لِيَجْزِىَ قَوْمًۢا بِمَا كَانُوا۟ يَكْسِبُونَ','18ed67eed45d032bb860af406bdc0018a367329b1d3bf0add68da558e6691952',25,500,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4488,45,15,'مَنْ عَمِلَ صَـٰلِحًا فَلِنَفْسِهِۦ ۖ وَمَنْ أَسَآءَ فَعَلَيْهَا ۖ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ','e5a7cefe0f88cc47c082374d120cbc15e02d8a11eb355c930e94733ea803d02f',25,500,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4489,45,16,'وَلَقَدْ ءَاتَيْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ وَرَزَقْنَـٰهُم مِّنَ ٱلطَّيِّبَـٰتِ وَفَضَّلْنَـٰهُمْ عَلَى ٱلْعَـٰلَمِينَ','aec894ad443e3b285c6789b8e39c2bbc95487a2f9351f48b78310fd806216fd4',25,500,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4490,45,17,'وَءَاتَيْنَـٰهُم بَيِّنَـٰتٍ مِّنَ ٱلْأَمْرِ ۖ فَمَا ٱخْتَلَفُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ','3925c36dd613fdf4d20d6fbcd89dd82a742b79433ce10a7972012304bfaffe80',25,500,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4491,45,18,'ثُمَّ جَعَلْنَـٰكَ عَلَىٰ شَرِيعَةٍ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ','35f89a6b2987582bca3cf98dc9899c92feb09add2dec825a2cd3c08a8f96823c',25,500,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4492,45,19,'إِنَّهُمْ لَن يُغْنُوا۟ عَنكَ مِنَ ٱللَّهِ شَيْـًٔا ۚ وَإِنَّ ٱلظَّـٰلِمِينَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۖ وَٱللَّهُ وَلِىُّ ٱلْمُتَّقِينَ','72579f048cd4f996d41b8b75d44a5c8ddfb4cfbd94122cd91c50b3caba984973',25,500,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4493,45,20,'هَـٰذَا بَصَـٰٓئِرُ لِلنَّاسِ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُوقِنُونَ','e1bc5c680883c7ffddc3aab8e0e6804021a710f0c92f4dd1e39345844f6f0be1',25,500,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4494,45,21,'أَمْ حَسِبَ ٱلَّذِينَ ٱجْتَرَحُوا۟ ٱلسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَوَآءً مَّحْيَاهُمْ وَمَمَاتُهُمْ ۚ سَآءَ مَا يَحْكُمُونَ','c87f1eee22ccb54c8f4f5f06d4d069891e5457f10fb99cf7783568c4f25b74c6',25,500,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4495,45,22,'وَخَلَقَ ٱللَّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ','cc9faa0a4bb1bee7e8692d3d0d4496e0ba96ca414287e9c8719d978b77838516',25,500,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4496,45,23,'أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَـٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلْمٍ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَـٰوَةً فَمَن يَهْدِيهِ مِنۢ بَعْدِ ٱللَّهِ ۚ أَفَلَا تَذَكَّرُونَ','902c0b9fbbea7b6422a9040f327d83945b3683e1e9d6ad42d1c7ca3a1600fc49',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4497,45,24,'وَقَالُوا۟ مَا هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَآ إِلَّا ٱلدَّهْرُ ۚ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَظُنُّونَ','818dd11c0dd81539de3c40ef43d1f635df1ab904df7c725c10e1de958ed0fcc4',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4498,45,25,'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا بَيِّنَـٰتٍ مَّا كَانَ حُجَّتَهُمْ إِلَّآ أَن قَالُوا۟ ٱئْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَـٰدِقِينَ','f65f8005cf66fe4f6347e8f92b11a7fae472927a1637ce958f421f7b82336d57',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4499,45,26,'قُلِ ٱللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ','1476509b8b422040b9db779e12c41dff0f9d03c77147e7eb80129ace6e2a929d',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4500,45,27,'وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَخْسَرُ ٱلْمُبْطِلُونَ','163b90f75bc1fd7508bcef6bca87c64933b01afde6688556c0103c73eb1bd5e9',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4501,45,28,'وَتَرَىٰ كُلَّ أُمَّةٍ جَاثِيَةً ۚ كُلُّ أُمَّةٍ تُدْعَىٰٓ إِلَىٰ كِتَـٰبِهَا ٱلْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ','eee14220488dc58e94fe0a95c7b693e417558064e049090e66974cd4649cc8d4',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4502,45,29,'هَـٰذَا كِتَـٰبُنَا يَنطِقُ عَلَيْكُم بِٱلْحَقِّ ۚ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ','28eb808d40bbd8cedb5b50a21fe628f402ad5fc99bca42863671a62f537432e8',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4503,45,30,'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِى رَحْمَتِهِۦ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْمُبِينُ','0a1a9fc43819c8cde90e0e068b34708d19b7093f428948a709f3e23e38d05a11',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4504,45,31,'وَأَمَّا ٱلَّذِينَ كَفَرُوٓا۟ أَفَلَمْ تَكُنْ ءَايَـٰتِى تُتْلَىٰ عَلَيْكُمْ فَٱسْتَكْبَرْتُمْ وَكُنتُمْ قَوْمًا مُّجْرِمِينَ','8e4721cac40b58aadb88278e8592fa9edae8fb6c5bb02b013e4dbe877d929a20',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4505,45,32,'وَإِذَا قِيلَ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱلسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِى مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنًّا وَمَا نَحْنُ بِمُسْتَيْقِنِينَ','1b4bd78ee6b355c0f0b23fef16941c3357a2db0bbdf47d6f67e0ab59ea95e2f9',25,501,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4506,45,33,'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','d9077c6e228a429516891c19722638f2fd02a4f2255abae04d8a805869d3bf8f',25,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4507,45,34,'وَقِيلَ ٱلْيَوْمَ نَنسَىٰكُمْ كَمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِينَ','33545346c05130cc9e145b85d3891a04395e64bfd43dec5e7e9734e698964b90',25,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4508,45,35,'ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذْتُمْ ءَايَـٰتِ ٱللَّهِ هُزُوًا وَغَرَّتْكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ فَٱلْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ','a9cb74c86b97daec71516ff3473da1bf193f48af153da3cf0cefd962e7927e70',25,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4509,45,36,'فَلِلَّهِ ٱلْحَمْدُ رَبِّ ٱلسَّمَـٰوَٰتِ وَرَبِّ ٱلْأَرْضِ رَبِّ ٱلْعَـٰلَمِينَ','788613420de16a70574f0766f848e5401de4b94d2294563757fcd64625b67c6a',25,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4510,45,37,'وَلَهُ ٱلْكِبْرِيَآءُ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ','0371b9c61aef8399dce39a370f01c9fe432c6b7d238b575a4a71be652d3cf5eb',25,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4511,46,1,'حمٓ','dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0',26,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4512,46,2,'تَنزِيلُ ٱلْكِتَـٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ','57bdb6c46ebf6ea8df147e2a49f13499f565445519713f875e038d63dd2f0925',26,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4513,46,3,'مَا خَلَقْنَا ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى ۚ وَٱلَّذِينَ كَفَرُوا۟ عَمَّآ أُنذِرُوا۟ مُعْرِضُونَ','252e5bc77a63c8e2e46e0652eb10aeb9ba1587cc7389ff0cc0c45f4b819285db',26,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4514,46,4,'قُلْ أَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَـٰوَٰتِ ۖ ٱئْتُونِى بِكِتَـٰبٍ مِّن قَبْلِ هَـٰذَآ أَوْ أَثَـٰرَةٍ مِّنْ عِلْمٍ إِن كُنتُمْ صَـٰدِقِينَ','a4002e88a657854c95049f5aedca3a42f280df9412abfc4fb1577ce798f5776e',26,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4515,46,5,'وَمَنْ أَضَلُّ مِمَّن يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا يَسْتَجِيبُ لَهُۥٓ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ وَهُمْ عَن دُعَآئِهِمْ غَـٰفِلُونَ','2cdef0570b588d424f6e39d6b683313cfe58cad2e853caf5c913b39eafd1bb81',26,502,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4516,46,6,'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمْ أَعْدَآءً وَكَانُوا۟ بِعِبَادَتِهِمْ كَـٰفِرِينَ','a49c15700110b5cb2b9fff90c0a58e478dd2d72505b576e24a6acba7c494561d',26,503,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4517,46,7,'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا بَيِّنَـٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ هَـٰذَا سِحْرٌ مُّبِينٌ','fa17462e5a651ebfa8cfded6e6b0bb34e6e60fc92b55741bc7d121d3e197834a',26,503,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4518,46,8,'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَلَا تَمْلِكُونَ لِى مِنَ ٱللَّهِ شَيْـًٔا ۖ هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ ۖ كَفَىٰ بِهِۦ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ ۖ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ','290080e03fec89f8408ef0d6bfb2a05a4416d86e8e5335443c07432b5bb22dcd',26,503,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4519,46,9,'قُلْ مَا كُنتُ بِدْعًا مِّنَ ٱلرُّسُلِ وَمَآ أَدْرِى مَا يُفْعَلُ بِى وَلَا بِكُمْ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ','3501e73bc7e25bcab694260667cfba854e77a2629de42fa6df7330a09696ed5c',26,503,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4520,46,10,'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَٱسْتَكْبَرْتُمْ ۖ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ','04497a60fafe64b7f99ee890aa11734d9768c0ddcac2a6e4cfd66b79d8293a7e',26,503,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4521,46,11,'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ لَوْ كَانَ خَيْرًا مَّا سَبَقُونَآ إِلَيْهِ ۚ وَإِذْ لَمْ يَهْتَدُوا۟ بِهِۦ فَسَيَقُولُونَ هَـٰذَآ إِفْكٌ قَدِيمٌ','fb4edfd03772473086140e01b3ed52aee26507ba3705fcaab9f9fd16e2dc4595',26,503,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4522,46,12,'وَمِن قَبْلِهِۦ كِتَـٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً ۚ وَهَـٰذَا كِتَـٰبٌ مُّصَدِّقٌ لِّسَانًا عَرَبِيًّا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُوا۟ وَبُشْرَىٰ لِلْمُحْسِنِينَ','83e2fc76ca34e4dfb177524bad20a2488daa20da1201d4499526df3022f78c6b',26,503,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4523,46,13,'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَـٰمُوا۟ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','e19fa68e3efd882e157d9a63300ffef4e4b97eb627da31499d474708d7de07e2',26,503,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4524,46,14,'أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ خَـٰلِدِينَ فِيهَا جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ','ce41b8f02c3f0492edab5d4a81cc50b1f647acb2418f8ba39a54cf6277852bfe',26,503,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4525,46,15,'وَوَصَّيْنَا ٱلْإِنسَـٰنَ بِوَٰلِدَيْهِ إِحْسَـٰنًا ۖ حَمَلَتْهُ أُمُّهُۥ كُرْهًا وَوَضَعَتْهُ كُرْهًا ۖ وَحَمْلُهُۥ وَفِصَـٰلُهُۥ ثَلَـٰثُونَ شَهْرًا ۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرْبَعِينَ سَنَةً قَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَـٰلِحًا تَرْضَىٰهُ وَأَصْلِحْ لِى فِى ذُرِّيَّتِىٓ ۖ إِنِّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ ٱلْمُسْلِمِينَ','dd7bdb3e15210adf68f5395d0909acabc8619132f85e9e3d3fe7b263d4c15ffb',26,504,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4526,46,16,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِىٓ أَصْحَـٰبِ ٱلْجَنَّةِ ۖ وَعْدَ ٱلصِّدْقِ ٱلَّذِى كَانُوا۟ يُوعَدُونَ','62b412466da1cccea321b9cbc71a4cc53b6a76e71ae2c1f33262bf634a61fea9',26,504,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4527,46,17,'وَٱلَّذِى قَالَ لِوَٰلِدَيْهِ أُفٍّ لَّكُمَآ أَتَعِدَانِنِىٓ أَنْ أُخْرَجَ وَقَدْ خَلَتِ ٱلْقُرُونُ مِن قَبْلِى وَهُمَا يَسْتَغِيثَانِ ٱللَّهَ وَيْلَكَ ءَامِنْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَيَقُولُ مَا هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ','821556a037b848fe806bffdb21e1baba0423e2c03a6aebbcb216f70218f31df9',26,504,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4528,46,18,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ إِنَّهُمْ كَانُوا۟ خَـٰسِرِينَ','059190526f2469eb1fe870f2eecee78ec386ef80d23c1b187671a5d0aecfd184',26,504,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4529,46,19,'وَلِكُلٍّ دَرَجَـٰتٌ مِّمَّا عَمِلُوا۟ ۖ وَلِيُوَفِّيَهُمْ أَعْمَـٰلَهُمْ وَهُمْ لَا يُظْلَمُونَ','66266c650b606a93331bdb5a4c91c2d91bff6ab0a895e285c9c7b7915e9ad678',26,504,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4530,46,20,'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذْهَبْتُمْ طَيِّبَـٰتِكُمْ فِى حَيَاتِكُمُ ٱلدُّنْيَا وَٱسْتَمْتَعْتُم بِهَا فَٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ','46b8c64e00018c0344583539fdc6fd95958643855899c39d701737554013dd22',26,504,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4531,46,21,'وَٱذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُۥ بِٱلْأَحْقَافِ وَقَدْ خَلَتِ ٱلنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ','cedfc2ca8c2c85ee28b87853763b67bb9b03b8e401a025fa4d65b5d33cad70a3',26,505,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4532,46,22,'قَالُوٓا۟ أَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ','c39f8703dde6410a35534ae869c7ee25f6decd702482b556815a6a17124eb326',26,505,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4533,46,23,'قَالَ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَـٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ','ea1c33c40a0e18601b8a6341d9596bfb06f290ff9baba03a1b33f232f446420c',26,505,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4534,46,24,'فَلَمَّا رَأَوْهُ عَارِضًا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا۟ هَـٰذَا عَارِضٌ مُّمْطِرُنَا ۚ بَلْ هُوَ مَا ٱسْتَعْجَلْتُم بِهِۦ ۖ رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ','c56f79c55e2bce2fa7da837fbdd03d123076002ddbe941a42bfcd9b692c27283',26,505,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4535,46,25,'تُدَمِّرُ كُلَّ شَىْءٍۭ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا۟ لَا يُرَىٰٓ إِلَّا مَسَـٰكِنُهُمْ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ','88a0c94d35a8c2c1696c5b4ac59afff0570ed2576f32b6f9bf494440424795f3',26,505,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4536,46,26,'وَلَقَدْ مَكَّنَّـٰهُمْ فِيمَآ إِن مَّكَّنَّـٰكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًا وَأَبْصَـٰرًا وَأَفْـِٔدَةً فَمَآ أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَآ أَبْصَـٰرُهُمْ وَلَآ أَفْـِٔدَتُهُم مِّن شَىْءٍ إِذْ كَانُوا۟ يَجْحَدُونَ بِـَٔايَـٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','2e645e5639984e359449ac2e8575d36e6f885ead69acf99b8a95c44aa7b1ef4f',26,505,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4537,46,27,'وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ ٱلْقُرَىٰ وَصَرَّفْنَا ٱلْـَٔايَـٰتِ لَعَلَّهُمْ يَرْجِعُونَ','66af487cdc5b6a55ef48ac40417f8fec8588578cfb17473a0a7dee7d1f5505ed',26,505,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4538,46,28,'فَلَوْلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرْبَانًا ءَالِهَةًۢ ۖ بَلْ ضَلُّوا۟ عَنْهُمْ ۚ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا۟ يَفْتَرُونَ','980b52558828680483760603edd5e326a77c77d0f371910539d3944ba4c4c538',26,505,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4539,46,29,'وَإِذْ صَرَفْنَآ إِلَيْكَ نَفَرًا مِّنَ ٱلْجِنِّ يَسْتَمِعُونَ ٱلْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓا۟ أَنصِتُوا۟ ۖ فَلَمَّا قُضِىَ وَلَّوْا۟ إِلَىٰ قَوْمِهِم مُّنذِرِينَ','c920a2b92fd59c6edbb09f1e8848b1960a647e19caf7a777244502644e418780',26,506,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4540,46,30,'قَالُوا۟ يَـٰقَوْمَنَآ إِنَّا سَمِعْنَا كِتَـٰبًا أُنزِلَ مِنۢ بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِىٓ إِلَى ٱلْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ','a2d618f2d52d85f5f1b3eba16c4fd3169eba433718b870b0bfd4b866a1715632',26,506,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4541,46,31,'يَـٰقَوْمَنَآ أَجِيبُوا۟ دَاعِىَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ','05d8ed99281fb9d88aa63257b41201c4c117091b1f02a892f7df58cfd87d1259',26,506,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4542,46,32,'وَمَن لَّا يُجِبْ دَاعِىَ ٱللَّهِ فَلَيْسَ بِمُعْجِزٍ فِى ٱلْأَرْضِ وَلَيْسَ لَهُۥ مِن دُونِهِۦٓ أَوْلِيَآءُ ۚ أُو۟لَـٰٓئِكَ فِى ضَلَـٰلٍ مُّبِينٍ','401508617c5cf9c2a8893c13e04d408cd96da92e661b6f93b785e05caedf313d',26,506,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4543,46,33,'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَلَمْ يَعْىَ بِخَلْقِهِنَّ بِقَـٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ ۚ بَلَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','ae3ca4ba5cbf779c7f2cde5eecb7eb25156dc38035a8ec87a049ccff362e3d2b',26,506,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4544,46,34,'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَيْسَ هَـٰذَا بِٱلْحَقِّ ۖ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ','62de81143347f9c655f4c817728bda92ade52449d32fb7daa51a459065235e3c',26,506,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4545,46,35,'فَٱصْبِرْ كَمَا صَبَرَ أُو۟لُوا۟ ٱلْعَزْمِ مِنَ ٱلرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ ۚ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّن نَّهَارٍۭ ۚ بَلَـٰغٌ ۚ فَهَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلْفَـٰسِقُونَ','cc16d1987c16682de8e4372d214eefe98b4a3d7cd4add2a00931152cafc6c5f1',26,506,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4546,47,1,'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعْمَـٰلَهُمْ','fb0f0f1814347ece9bb7770c6aea8ff1fb58b18ac51fccd195676201f77edc93',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4547,47,2,'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٍ وَهُوَ ٱلْحَقُّ مِن رَّبِّهِمْ ۙ كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَأَصْلَحَ بَالَهُمْ','7f2c76e371ff6b6b09eb58c2541e0c5c7209471c1aa315cc52663cd655dfe010',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4548,47,3,'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلْبَـٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلْحَقَّ مِن رَّبِّهِمْ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ لِلنَّاسِ أَمْثَـٰلَهُمْ','2f8b2185fd4840c37ff9782d935dde0d69e99703bf34ca411c7298427aba8e77',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4549,47,4,'فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ فَضَرْبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثْخَنتُمُوهُمْ فَشُدُّوا۟ ٱلْوَثَاقَ فَإِمَّا مَنًّۢا بَعْدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلْحَرْبُ أَوْزَارَهَا ۚ ذَٰلِكَ وَلَوْ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنْهُمْ وَلَـٰكِن لِّيَبْلُوَا۟ بَعْضَكُم بِبَعْضٍ ۗ وَٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعْمَـٰلَهُمْ','ac387523fc5da2b8cfd09efafa1ba37fb2700ee492977a7a33483350b4f1cecd',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4550,47,5,'سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ','e5e561944351613e369e0a79c9dd7b53eb6bbef216b6dc1910c2b5e6b8f2fc94',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4551,47,6,'وَيُدْخِلُهُمُ ٱلْجَنَّةَ عَرَّفَهَا لَهُمْ','ebe99776efdde7a54362e58f73a0cfe9c6563f373593935c9b27865200508525',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4552,47,7,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ','e8b71a5db49d19dcd6d232e7f1a03244ad82c6be50b6f230a1e205797f32bcb9',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4553,47,8,'وَٱلَّذِينَ كَفَرُوا۟ فَتَعْسًا لَّهُمْ وَأَضَلَّ أَعْمَـٰلَهُمْ','49d34e41c4fcfe2e6e6bba258ac8acc5c17da678281f8f40a4ee345fc9bb0a4e',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4554,47,9,'ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا۟ مَآ أَنزَلَ ٱللَّهُ فَأَحْبَطَ أَعْمَـٰلَهُمْ','f918ed705e866d57b22237478ac9d05a7d69995a7168b5e8ef3ee338f128a414',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4555,47,10,'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ دَمَّرَ ٱللَّهُ عَلَيْهِمْ ۖ وَلِلْكَـٰفِرِينَ أَمْثَـٰلُهَا','3b7f7fffbdd3f25c1d2520ae20c3aa37b7322845fd76714cfa6c4ebc7a575245',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4556,47,11,'ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوْلَى ٱلَّذِينَ ءَامَنُوا۟ وَأَنَّ ٱلْكَـٰفِرِينَ لَا مَوْلَىٰ لَهُمْ','3604cb609e48871bb42149595dbd7258da0a6a1f914037600dac55edab46bccb',26,507,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4557,47,12,'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ وَٱلَّذِينَ كَفَرُوا۟ يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ ٱلْأَنْعَـٰمُ وَٱلنَّارُ مَثْوًى لَّهُمْ','ef84de425b4e84fe545bceb77adb554420a40627a33ee67fb3fe0c35d837e631',26,508,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4558,47,13,'وَكَأَيِّن مِّن قَرْيَةٍ هِىَ أَشَدُّ قُوَّةً مِّن قَرْيَتِكَ ٱلَّتِىٓ أَخْرَجَتْكَ أَهْلَكْنَـٰهُمْ فَلَا نَاصِرَ لَهُمْ','c8b5437498e691bd9ee89b13831227cb9c98b67d7093fec23b98699035bfbcb3',26,508,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4559,47,14,'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُم','44c1bfb570c83ffaa34f92233abcf3a7e82520be452f1d062a318e1ba74faa3a',26,508,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4560,47,15,'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۖ فِيهَآ أَنْهَـٰرٌ مِّن مَّآءٍ غَيْرِ ءَاسِنٍ وَأَنْهَـٰرٌ مِّن لَّبَنٍ لَّمْ يَتَغَيَّرْ طَعْمُهُۥ وَأَنْهَـٰرٌ مِّنْ خَمْرٍ لَّذَّةٍ لِّلشَّـٰرِبِينَ وَأَنْهَـٰرٌ مِّنْ عَسَلٍ مُّصَفًّى ۖ وَلَهُمْ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغْفِرَةٌ مِّن رَّبِّهِمْ ۖ كَمَنْ هُوَ خَـٰلِدٌ فِى ٱلنَّارِ وَسُقُوا۟ مَآءً حَمِيمًا فَقَطَّعَ أَمْعَآءَهُمْ','762eb63a417b45dc20c39909854df9c5afb05c70bbe7a8e5430cdc26e20fbb4e',26,508,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4561,47,16,'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُوا۟ مِنْ عِندِكَ قَالُوا۟ لِلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مَاذَا قَالَ ءَانِفًا ۚ أُو۟لَـٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ','f3f0801b499a3456c2c60ba94748546888be9f0e7a840b42053983b891738fa0',26,508,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4562,47,17,'وَٱلَّذِينَ ٱهْتَدَوْا۟ زَادَهُمْ هُدًى وَءَاتَىٰهُمْ تَقْوَىٰهُمْ','90b1c935b2e36520e073c505a306a17fdcf79b3fe972e8af048d66eaa01a08ad',26,508,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4563,47,18,'فَهَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً ۖ فَقَدْ جَآءَ أَشْرَاطُهَا ۚ فَأَنَّىٰ لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَىٰهُمْ','70e2d0214733b3119e2809b5a803de6d564d4a584dc7080f9796a8c10f90a07e',26,508,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4564,47,19,'فَٱعْلَمْ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ۗ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ','3ea5df544501e149e4ef1873ec3517c5bbe7ca2b039453ce445fe76eeaa7918a',26,508,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4565,47,20,'وَيَقُولُ ٱلَّذِينَ ءَامَنُوا۟ لَوْلَا نُزِّلَتْ سُورَةٌ ۖ فَإِذَآ أُنزِلَتْ سُورَةٌ مُّحْكَمَةٌ وَذُكِرَ فِيهَا ٱلْقِتَالُ ۙ رَأَيْتَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يَنظُرُونَ إِلَيْكَ نَظَرَ ٱلْمَغْشِىِّ عَلَيْهِ مِنَ ٱلْمَوْتِ ۖ فَأَوْلَىٰ لَهُمْ','60b153507cdd340dc6be15524c679fefb82bfa0c110521c40a0e11147260bfcd',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4566,47,21,'طَاعَةٌ وَقَوْلٌ مَّعْرُوفٌ ۚ فَإِذَا عَزَمَ ٱلْأَمْرُ فَلَوْ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَيْرًا لَّهُمْ','36484196cf6ef1e0a074974fd9e32ec9207b2bb6f484cf38356f04d27a104b2a',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4567,47,22,'فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا۟ فِى ٱلْأَرْضِ وَتُقَطِّعُوٓا۟ أَرْحَامَكُمْ','945fbc06d69b45501424eac4a049dbd7ab05ad42b4ca366b996c48c1d9113be0',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4568,47,23,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰٓ أَبْصَـٰرَهُمْ','27efece1ae07e3d5b7dddc20fc1644ccf1f720c8daddd1cda540fe6a5e88223d',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4569,47,24,'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَآ','0d81fbb33547427bbedfbfab76efbbaf5af53f3b5f796bd921b7e38268181691',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4570,47,25,'إِنَّ ٱلَّذِينَ ٱرْتَدُّوا۟ عَلَىٰٓ أَدْبَـٰرِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَى ۙ ٱلشَّيْطَـٰنُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ','a8358e480e6545bbacde00a6ee1fe290571a0b41a9f82cc87a437842596e8f74',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4571,47,26,'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لِلَّذِينَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ ٱلْأَمْرِ ۖ وَٱللَّهُ يَعْلَمُ إِسْرَارَهُمْ','626bbb93b9304aac488af61384ab2faff1955326a9575c936ecc06cb350ccc32',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4572,47,27,'فَكَيْفَ إِذَا تَوَفَّتْهُمُ ٱلْمَلَـٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَـٰرَهُمْ','4a808d0a4341bd80ac4e4a5860dbf843bf6bc5a79006bcef6150e7285aad756b',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4573,47,28,'ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَآ أَسْخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضْوَٰنَهُۥ فَأَحْبَطَ أَعْمَـٰلَهُمْ','3486cc91c5bcfbf73a90b08e255b276a543abe5643cde0f5f355c4cdb2eb563d',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4574,47,29,'أَمْ حَسِبَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ ٱللَّهُ أَضْغَـٰنَهُمْ','67fa5b5ee82098eeb09be782d0ea0f6c52e5bdd805365ebe927ab2d4cefe567d',26,509,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4575,47,30,'وَلَوْ نَشَآءُ لَأَرَيْنَـٰكَهُمْ فَلَعَرَفْتَهُم بِسِيمَـٰهُمْ ۚ وَلَتَعْرِفَنَّهُمْ فِى لَحْنِ ٱلْقَوْلِ ۚ وَٱللَّهُ يَعْلَمُ أَعْمَـٰلَكُمْ','806841b63905a8ad040723699e7248c8e984ed98bbc296cad5b4d0513bac15e9',26,510,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4576,47,31,'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَـٰهِدِينَ مِنكُمْ وَٱلصَّـٰبِرِينَ وَنَبْلُوَا۟ أَخْبَارَكُمْ','e54f59f3ce6655f0fd6076322d4b5847b204b3a42314587a52c8bd29778fc475',26,510,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4577,47,32,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ وَشَآقُّوا۟ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَىٰ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَسَيُحْبِطُ أَعْمَـٰلَهُمْ','7665abb5eb9bd6a20c4b53cd02e26e90429900464dac9292668a120fe2028cab',26,510,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4578,47,33,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَلَا تُبْطِلُوٓا۟ أَعْمَـٰلَكُمْ','5a6869cc87f854f84b635141c55f700265ae621653da8433edf26a086f48c3cf',26,510,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4579,47,34,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ','043ba7b088cae36fd96d085eb7e10aec7fb92feb27e88ab565925bf303e305ea',26,510,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4580,47,35,'فَلَا تَهِنُوا۟ وَتَدْعُوٓا۟ إِلَى ٱلسَّلْمِ وَأَنتُمُ ٱلْأَعْلَوْنَ وَٱللَّهُ مَعَكُمْ وَلَن يَتِرَكُمْ أَعْمَـٰلَكُمْ','a152fe306c9fdde811dc292a60fd021421cc684c6e43460adf867aab9f63b243',26,510,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4581,47,36,'إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ','9ae5f8b378cbe4af8c0865e231cd72e7c97e44d071fff542543e2105f0715937',26,510,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4582,47,37,'إِن يَسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا۟ وَيُخْرِجْ أَضْغَـٰنَكُمْ','7fc6dc8ac620f6c7fe40dff0b69530b7dd229a0a3e9a59d9bfe8fe4c9eee9ee9',26,510,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4583,47,38,'هَـٰٓأَنتُمْ هَـٰٓؤُلَآءِ تُدْعَوْنَ لِتُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبْخَلُ ۖ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِۦ ۚ وَٱللَّهُ ٱلْغَنِىُّ وَأَنتُمُ ٱلْفُقَرَآءُ ۚ وَإِن تَتَوَلَّوْا۟ يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوٓا۟ أَمْثَـٰلَكُم','c042b94da670b2b18ada8d4ca412f7390645ff64fb8c5558dcf415f0734b2eb3',26,510,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4584,48,1,'إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا','723bb49a70eac15d357a7ac5780f74cb01e75badcb3f56a323ebed5ec3641fcc',26,511,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4585,48,2,'لِّيَغْفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُۥ عَلَيْكَ وَيَهْدِيَكَ صِرَٰطًا مُّسْتَقِيمًا','1783840d4c2b765754c17073bd959cf1b869bcb33b4797cc18296251c1bd9533',26,511,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4586,48,3,'وَيَنصُرَكَ ٱللَّهُ نَصْرًا عَزِيزًا','9e77616709f3ea4c55d6586f90bc6ffca8e0e41912be449b5661ac201763c955',26,511,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4587,48,4,'هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ لِيَزْدَادُوٓا۟ إِيمَـٰنًا مَّعَ إِيمَـٰنِهِمْ ۗ وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','4e380b19f8a1b2651fc50801c56fb52378021bbdf22c7b36f0b5cd4169a51a08',26,511,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4588,48,5,'لِّيُدْخِلَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ ۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوْزًا عَظِيمًا','a683bd0fc000a67de48b45e9373068eef4a1de4bb1022fb82f2db64a4f55cd96',26,511,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4589,48,6,'وَيُعَذِّبَ ٱلْمُنَـٰفِقِينَ وَٱلْمُنَـٰفِقَـٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَـٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوْءِ ۚ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ ۖ وَغَضِبَ ٱللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًا','b3e2b2bc05cc92e61f6ec8997734c88c83b4685a4c5627a051b029836e0b4835',26,511,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4590,48,7,'وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا','fae97b3c22abcf5ed5a687e8968c55c7647bd3b31f7807fa7fffcc0161478974',26,511,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4591,48,8,'إِنَّآ أَرْسَلْنَـٰكَ شَـٰهِدًا وَمُبَشِّرًا وَنَذِيرًا','119163b04d6d497026147f32e276262da9699869712e68dfee5219b7e558ff89',26,511,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4592,48,9,'لِّتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَةً وَأَصِيلًا','83289fdc8429590918213f2ad39848ec13f8b80382839826d3c0198b2cec39c2',26,511,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4593,48,10,'إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوْقَ أَيْدِيهِمْ ۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِۦ ۖ وَمَنْ أَوْفَىٰ بِمَا عَـٰهَدَ عَلَيْهُ ٱللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًا','76fe35c1cc78990a8a15a0da9a56ee7962c1042f83aeeceaa34ba46792157d87',26,512,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4594,48,11,'سَيَقُولُ لَكَ ٱلْمُخَلَّفُونَ مِنَ ٱلْأَعْرَابِ شَغَلَتْنَآ أَمْوَٰلُنَا وَأَهْلُونَا فَٱسْتَغْفِرْ لَنَا ۚ يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۚ قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًۢا ۚ بَلْ كَانَ ٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرًۢا','7cf73c4b662cd3932872732c774f2cd450a551cac179df066ac7e939aaaa387d',26,512,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4595,48,12,'بَلْ ظَنَنتُمْ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلْمُؤْمِنُونَ إِلَىٰٓ أَهْلِيهِمْ أَبَدًا وَزُيِّنَ ذَٰلِكَ فِى قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ ٱلسَّوْءِ وَكُنتُمْ قَوْمًۢا بُورًا','a99633b1386b81d3cc5275e0a8cc7ad9c29edfb0a5822006796db75b0983b79c',26,512,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4596,48,13,'وَمَن لَّمْ يُؤْمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعْتَدْنَا لِلْكَـٰفِرِينَ سَعِيرًا','f3dd0109ec0b51b219b68d927551166c0b53c94151a8686a02a27a524572164a',26,512,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4597,48,14,'وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا','71b9f399a498a897387bcfb48715781a3fac9e0c62b882851198c4bf52d72661',26,512,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4598,48,15,'سَيَقُولُ ٱلْمُخَلَّفُونَ إِذَا ٱنطَلَقْتُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ ۖ يُرِيدُونَ أَن يُبَدِّلُوا۟ كَلَـٰمَ ٱللَّهِ ۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمْ قَالَ ٱللَّهُ مِن قَبْلُ ۖ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا ۚ بَلْ كَانُوا۟ لَا يَفْقَهُونَ إِلَّا قَلِيلًا','6cce2cf7bda15603aac38e9e4a3e7a6704bfedc4957fcc7926912ee049437b0f',26,512,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4599,48,16,'قُل لِّلْمُخَلَّفِينَ مِنَ ٱلْأَعْرَابِ سَتُدْعَوْنَ إِلَىٰ قَوْمٍ أُو۟لِى بَأْسٍ شَدِيدٍ تُقَـٰتِلُونَهُمْ أَوْ يُسْلِمُونَ ۖ فَإِن تُطِيعُوا۟ يُؤْتِكُمُ ٱللَّهُ أَجْرًا حَسَنًا ۖ وَإِن تَتَوَلَّوْا۟ كَمَا تَوَلَّيْتُم مِّن قَبْلُ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا','86f328dc69d7fbf0f9dc275f1471a7c15b9abb6ceaa48ba0968b68aa91d7f4e1',26,513,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4600,48,17,'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ ۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ وَمَن يَتَوَلَّ يُعَذِّبْهُ عَذَابًا أَلِيمًا','43d70bd3cb96a379c5806ae3848143bb93559e6cf5f338e4b5ee4b93e35745b1',26,513,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4601,48,18,'لَّقَدْ رَضِىَ ٱللَّهُ عَنِ ٱلْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيْهِمْ وَأَثَـٰبَهُمْ فَتْحًا قَرِيبًا','135d03509f794381fe1c3440883ceb63c5cd499cfb2c249a30afccb4501b6d7f',26,513,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4602,48,19,'وَمَغَانِمَ كَثِيرَةً يَأْخُذُونَهَا ۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا','af57e7fbe1f5a6b6b279ff35ca33f1e1054884c301b0f8a707196d9fb72213d8',26,513,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4603,48,20,'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَـٰذِهِۦ وَكَفَّ أَيْدِىَ ٱلنَّاسِ عَنكُمْ وَلِتَكُونَ ءَايَةً لِّلْمُؤْمِنِينَ وَيَهْدِيَكُمْ صِرَٰطًا مُّسْتَقِيمًا','0c24c298370231a3208bffbd04e6f1847c7f3137847850f12378445dc9c667b0',26,513,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4604,48,21,'وَأُخْرَىٰ لَمْ تَقْدِرُوا۟ عَلَيْهَا قَدْ أَحَاطَ ٱللَّهُ بِهَا ۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا','f75022cbccd0005454d82dbd6e5bc373b58457ec77e5bf07dae7c1391fe24827',26,513,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4605,48,22,'وَلَوْ قَـٰتَلَكُمُ ٱلَّذِينَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلْأَدْبَـٰرَ ثُمَّ لَا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا','13334815b426dc99ef83025ef6e38b2ac9955249bdc77ec066b233a8621ccc72',26,513,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4606,48,23,'سُنَّةَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ مِن قَبْلُ ۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا','71a15be277b0cdbc5dbb2e5a6b027c61f60d970c9b2390ff2912fa2b846eca10',26,513,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4607,48,24,'وَهُوَ ٱلَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ ۚ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا','dccb2a4c6c0b35b34c0e0ccadaddd3181ec6616d3cf47547b37a9f5a82e4f4e6',26,514,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4608,48,25,'هُمُ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱلْهَدْىَ مَعْكُوفًا أَن يَبْلُغَ مَحِلَّهُۥ ۚ وَلَوْلَا رِجَالٌ مُّؤْمِنُونَ وَنِسَآءٌ مُّؤْمِنَـٰتٌ لَّمْ تَعْلَمُوهُمْ أَن تَطَـُٔوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةٌۢ بِغَيْرِ عِلْمٍ ۖ لِّيُدْخِلَ ٱللَّهُ فِى رَحْمَتِهِۦ مَن يَشَآءُ ۚ لَوْ تَزَيَّلُوا۟ لَعَذَّبْنَا ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابًا أَلِيمًا','36841f0bdd7f4cb5e815390cc7e077fc7d69e0420edd56758df537c137d98c81',26,514,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4609,48,26,'إِذْ جَعَلَ ٱلَّذِينَ كَفَرُوا۟ فِى قُلُوبِهِمُ ٱلْحَمِيَّةَ حَمِيَّةَ ٱلْجَـٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ ٱلتَّقْوَىٰ وَكَانُوٓا۟ أَحَقَّ بِهَا وَأَهْلَهَا ۚ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا','b5ae32da37331792901e4cb9d0109503f26b98da7a3dc059a5b744862aa7cbd9',26,514,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4610,48,27,'لَّقَدْ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءْيَا بِٱلْحَقِّ ۖ لَتَدْخُلُنَّ ٱلْمَسْجِدَ ٱلْحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ ۖ فَعَلِمَ مَا لَمْ تَعْلَمُوا۟ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحًا قَرِيبًا','fcd44da2ba20c5aa731f570efe489d0fdc3579f37a2d856601b380b32f9a09ff',26,514,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4611,48,28,'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا','432f454e05fc8138dbf23154f793f225a0c967926cad3ba4476996ba2bcc3b67',26,514,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4612,48,29,'مُّحَمَّدٌ رَّسُولُ ٱللَّهِ ۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ ۖ تَرَىٰهُمْ رُكَّعًا سُجَّدًا يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا ۖ سِيمَاهُمْ فِى وُجُوهِهِم مِّنْ أَثَرِ ٱلسُّجُودِ ۚ ذَٰلِكَ مَثَلُهُمْ فِى ٱلتَّوْرَىٰةِ ۚ وَمَثَلُهُمْ فِى ٱلْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَٱسْتَغْلَظَ فَٱسْتَوَىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلْكُفَّارَ ۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنْهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًۢا','1e38a68421bcf9cf14006cd156aa5c31f205642a471655815cbc047f792a6217',26,515,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4613,49,1,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَيْنَ يَدَىِ ٱللَّهِ وَرَسُولِهِۦ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ','0e8da0417cbec8be288fd674a45a87247f17d99b36ba73ba548671557a8fbe96',26,515,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4614,49,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَرْفَعُوٓا۟ أَصْوَٰتَكُمْ فَوْقَ صَوْتِ ٱلنَّبِىِّ وَلَا تَجْهَرُوا۟ لَهُۥ بِٱلْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَـٰلُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ','cc4e4415ad627f506a572fa4b44fe72f12dfbbafa7be377add1eedf7fc998c14',26,515,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4615,49,3,'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصْوَٰتَهُمْ عِندَ رَسُولِ ٱللَّهِ أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱمْتَحَنَ ٱللَّهُ قُلُوبَهُمْ لِلتَّقْوَىٰ ۚ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ','414847d77ad1e143ce5ed1e1703a5b5a89e3d68a333824ceef783e758c521d9f',26,515,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4616,49,4,'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلْحُجُرَٰتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ','f6941c009b762d6342d5b5a7c4d0fb7e7f9b0c60034875fbe68efb1454604af1',26,515,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4617,49,5,'وَلَوْ أَنَّهُمْ صَبَرُوا۟ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَّهُمْ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','f231d1f0b348896b63c832786f115c4be7599ca0e8a11a4c5d2455d5ba866e37',26,516,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4618,49,6,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَـٰلَةٍ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَـٰدِمِينَ','008ef7410d1cf9d4dcd8aba12f2f925c786856ff707cf36e3931e648743b5cf4',26,516,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4619,49,7,'وَٱعْلَمُوٓا۟ أَنَّ فِيكُمْ رَسُولَ ٱللَّهِ ۚ لَوْ يُطِيعُكُمْ فِى كَثِيرٍ مِّنَ ٱلْأَمْرِ لَعَنِتُّمْ وَلَـٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيْكُمُ ٱلْإِيمَـٰنَ وَزَيَّنَهُۥ فِى قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ ٱلْكُفْرَ وَٱلْفُسُوقَ وَٱلْعِصْيَانَ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ','5f9b64d90ffb8c1d648f62c0b4f19ec2357a200fcf54b61973e04ae8fb281525',26,516,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4620,49,8,'فَضْلًا مِّنَ ٱللَّهِ وَنِعْمَةً ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','22ac5900dd921f70338d22ac0e6f7760c38816311a1c4fae68d943ea0d0afe73',26,516,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4621,49,9,'وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا ۖ فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَـٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ ۚ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ ۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ','db44ecb288212a8e81afee995adbddd55c1f8f9407c7a3b64042ae12cbef4e6e',26,516,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4622,49,10,'إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ','bc9063abe975f25fbc6d9c31cdce0ee70cc17dc014ecadc7562ca84fd1ce1373',26,516,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4623,49,11,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَسْخَرْ قَوْمٌ مِّن قَوْمٍ عَسَىٰٓ أَن يَكُونُوا۟ خَيْرًا مِّنْهُمْ وَلَا نِسَآءٌ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيْرًا مِّنْهُنَّ ۖ وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَـٰبِ ۖ بِئْسَ ٱلِٱسْمُ ٱلْفُسُوقُ بَعْدَ ٱلْإِيمَـٰنِ ۚ وَمَن لَّمْ يَتُبْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ','ba3e734607df1a6482717f96734e1a67f17d9aa956db231274df0612adad2483',26,516,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4624,49,12,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌ ۖ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا ۚ أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ تَوَّابٌ رَّحِيمٌ','6a3472196fd9cbc525e9e7b84aca3c99ec0ad1f1ce849087980a8f0b767fe004',26,517,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4625,49,13,'يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَـٰكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَـٰكُمْ شُعُوبًا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ ۚ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ ۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌ','f2bac1388976aea218d38975297ee34955efd3785ddd0bb6d761c2b37710eb13',26,517,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4626,49,14,'قَالَتِ ٱلْأَعْرَابُ ءَامَنَّا ۖ قُل لَّمْ تُؤْمِنُوا۟ وَلَـٰكِن قُولُوٓا۟ أَسْلَمْنَا وَلَمَّا يَدْخُلِ ٱلْإِيمَـٰنُ فِى قُلُوبِكُمْ ۖ وَإِن تُطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتْكُم مِّنْ أَعْمَـٰلِكُمْ شَيْـًٔا ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','ab1f4860fb01d80e28e416bfd3716a4f2227e95105fcbde9b6b8fa1ce82c1556',26,517,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4627,49,15,'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُوا۟ وَجَـٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ','76debb29bdee5abaf0351f79daed956ed0e9ffce0cc942a5842457b5dd079b9c',26,517,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4628,49,16,'قُلْ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمْ وَٱللَّهُ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ','27e76e4581b4f5f0c453a1ba42297debd6497a935ac1fff88fbdc9c4ff57987f',26,517,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4629,49,17,'يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا۟ ۖ قُل لَّا تَمُنُّوا۟ عَلَىَّ إِسْلَـٰمَكُم ۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَىٰكُمْ لِلْإِيمَـٰنِ إِن كُنتُمْ صَـٰدِقِينَ','daaa7f54912fad0783baf8c6c490addf8d4264d204965fd51275e8998164e76a',26,517,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4630,49,18,'إِنَّ ٱللَّهَ يَعْلَمُ غَيْبَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا تَعْمَلُونَ','8022db772aa4ec4ff7036040f07c88b8275c55d7d25bb7ee1e92aa2f224a410b',26,517,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4631,50,1,'قٓ ۚ وَٱلْقُرْءَانِ ٱلْمَجِيدِ','a1ff549aa1323e3bec990c28f55d17ab63e1f876b357124ff02140c7f62b246f',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4632,50,2,'بَلْ عَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ فَقَالَ ٱلْكَـٰفِرُونَ هَـٰذَا شَىْءٌ عَجِيبٌ','c35fb0241e1049abd11b845e0975ff8e1c44210835fc81042c5e18a8ee46a51d',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4633,50,3,'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا ۖ ذَٰلِكَ رَجْعٌۢ بَعِيدٌ','69347bf2894f0afcdc785f68273ffa1c91270035c400f6917ef73f9ace72f4f1',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4634,50,4,'قَدْ عَلِمْنَا مَا تَنقُصُ ٱلْأَرْضُ مِنْهُمْ ۖ وَعِندَنَا كِتَـٰبٌ حَفِيظٌۢ','4d400dd9d03147389df797d5130b5fb4ec3c159645300d7461484663d3bc3691',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4635,50,5,'بَلْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَهُمْ فِىٓ أَمْرٍ مَّرِيجٍ','6fd0ea0772ec67c6ea4cac702e7cb991d88c08c45a7d7392ccac5a9e382847fc',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4636,50,6,'أَفَلَمْ يَنظُرُوٓا۟ إِلَى ٱلسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَـٰهَا وَزَيَّنَّـٰهَا وَمَا لَهَا مِن فُرُوجٍ','282282c2b3d270a918134437407a9adc8a2925ecde3e828e9d375c83a53bed59',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4637,50,7,'وَٱلْأَرْضَ مَدَدْنَـٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۭ بَهِيجٍ','dabf08d26ec93b314ee3251f670d77a88be92aff328908c5a9fd8001506ce9f7',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4638,50,8,'تَبْصِرَةً وَذِكْرَىٰ لِكُلِّ عَبْدٍ مُّنِيبٍ','fdcdb7489e8a3688d3ddc99090486b0ac2a313965f90a3d773437087d090d01f',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4639,50,9,'وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءً مُّبَـٰرَكًا فَأَنۢبَتْنَا بِهِۦ جَنَّـٰتٍ وَحَبَّ ٱلْحَصِيدِ','01d488bd779bb25b868798f62ac012676a4db4fc1ace6248aaf16b71731ee95d',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4640,50,10,'وَٱلنَّخْلَ بَاسِقَـٰتٍ لَّهَا طَلْعٌ نَّضِيدٌ','aa946596245e012ec8a9b02d7e5c18af86b935cd07a9457f31c96e122bf3be39',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4641,50,11,'رِّزْقًا لِّلْعِبَادِ ۖ وَأَحْيَيْنَا بِهِۦ بَلْدَةً مَّيْتًا ۚ كَذَٰلِكَ ٱلْخُرُوجُ','a6c053a1a43e2e6f2b22f38597affd88e768fae6ea4fb4768b9dd99a19a40a50',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4642,50,12,'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَأَصْحَـٰبُ ٱلرَّسِّ وَثَمُودُ','b8057f851d4aa5179c5dd68aac5ec37ea008647fb132addd92081fbc0daff747',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4643,50,13,'وَعَادٌ وَفِرْعَوْنُ وَإِخْوَٰنُ لُوطٍ','5fe248479f2b5dad37d3c878f6226e2258261c68e839e98e17ea313d51d6ce53',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4644,50,14,'وَأَصْحَـٰبُ ٱلْأَيْكَةِ وَقَوْمُ تُبَّعٍ ۚ كُلٌّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ','3566e7acf8b228040f22671c3c67521462e8714b066197b328632b6f3199e44a',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4645,50,15,'أَفَعَيِينَا بِٱلْخَلْقِ ٱلْأَوَّلِ ۚ بَلْ هُمْ فِى لَبْسٍ مِّنْ خَلْقٍ جَدِيدٍ','f6061af674abf8e850b5ed4893dffc72eb736c5dc3d035438d6156e8a7b93677',26,518,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4646,50,16,'وَلَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ ۖ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ','e81ca96d3c34650bc2fc5c3e02525266864e5f0543a7ca34de9e79b43bf2ca03',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4647,50,17,'إِذْ يَتَلَقَّى ٱلْمُتَلَقِّيَانِ عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٌ','9ed1b5f54f219dc8edb3419c402fd72a2ff3cc5456e42de912246dc7bb7e4963',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4648,50,18,'مَّا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ','9cac4976deaec6f797e50e36e76dbbc92c4a1bdd330080446bf45942dcca42c4',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4649,50,19,'وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ۖ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ','52a72989837d2ce5ee8b9f1f035bc3ad4cbe72b97dca463eb1e5fe43be0ca381',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4650,50,20,'وَنُفِخَ فِى ٱلصُّورِ ۚ ذَٰلِكَ يَوْمُ ٱلْوَعِيدِ','bbd6545830e90907db1614a6a9ef16f2c63ef8a69dec247b2c1663afd7d7f1a3',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4651,50,21,'وَجَآءَتْ كُلُّ نَفْسٍ مَّعَهَا سَآئِقٌ وَشَهِيدٌ','2a78f6815c45096dc40471da7e76e98397675108fbd1d800a9c7fcbceab99730',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4652,50,22,'لَّقَدْ كُنتَ فِى غَفْلَةٍ مِّنْ هَـٰذَا فَكَشَفْنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلْيَوْمَ حَدِيدٌ','81f367e54185fd51a7b351c58f0596f0da7b12a46bd18486befed2c1950620c2',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4653,50,23,'وَقَالَ قَرِينُهُۥ هَـٰذَا مَا لَدَىَّ عَتِيدٌ','4340ca7bfdf9d79c65a1691c660e0a0b161aa9d5de56e25716b3b0ae56db6d7d',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4654,50,24,'أَلْقِيَا فِى جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍ','fb3769ab078cf939d626870ab3c83a63303268151274e775d3eb3d3a31a87ed9',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4655,50,25,'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ مُّرِيبٍ','e9a7fe996c0955eaf1ebb58d3c08206fb41b4561142205f8abaa5589109226aa',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4656,50,26,'ٱلَّذِى جَعَلَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَأَلْقِيَاهُ فِى ٱلْعَذَابِ ٱلشَّدِيدِ','f3da1ab33af30a3d8a854a7d3c6f367a17c366bb78438375d23eae27ad617490',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4657,50,27,'قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ وَلَـٰكِن كَانَ فِى ضَلَـٰلٍۭ بَعِيدٍ','a882a8773ddd2eee9f50ef79814c7ef33fb939d8e9dd0520eb45c12244ccc199',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4658,50,28,'قَالَ لَا تَخْتَصِمُوا۟ لَدَىَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِٱلْوَعِيدِ','cc197f8a711d089b13156a094aaaa401c757f8acf9dcca591a368e940cd58ab5',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4659,50,29,'مَا يُبَدَّلُ ٱلْقَوْلُ لَدَىَّ وَمَآ أَنَا۠ بِظَلَّـٰمٍ لِّلْعَبِيدِ','541006a900bdbd3d52fac32138657978681bddc37de4071c16e605e8b79df54e',26,519,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (4660,50,30,'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدٍ','29943300d141dabdf54a1985933ff9b9acf644d8a342d33ce8e728b4e28763d2',26,519,1);
